# Initialize an empty dictionary to store student names and grades
student_grades = {}

def add_student(name, grade):
    """Add a new student to the dictionary with their name and grade."""
    if name in student_grades:
        print(f"{name} is already a student. Grade cannot be updated.")
    else:
        student_grades[name] = grade
        print(f"{name} has been added with a grade of {grade}.")

def update_grade(name, new_grade):
    """Update the grade of an existing student in the dictionary."""
    if name not in student_grades:
        print(f"{name} is not a student. Cannot update grade.")
    else:
        student_grades[name] = new_grade
        print(f"{name}'s grade has been updated to {new_grade}.")

def calculate_average():
    """Calculate and print the average grade of all students."""
    total_grade = sum(student_grades.values())
    num_students = len(student_grades)
    average_grade = total_grade / num_students
    print(f"Average: {average_grade:.2f}")

def main():
    while True:
        command = input("Enter a command (Add, Update, Calculate, or Exit): ").lower()

        if command == "add":
            name = input("Enter student name: ")
            grade = int(input("Enter grade: "))
            add_student(name, grade)

        elif command == "update":
            name = input("Enter student name: ")
            grade = int(input("Enter new grade: "))
            update_grade(name, grade)

        elif command == "calculate":
            calculate_average()

        elif command == "exit":
            print("Exiting the program...")
            break

        else:
            print("Invalid command. Please try again.")

if __name__ == "__main__":
    main()
```

This program allows users to add students, update their grades, and calculate the average grade of all students. The `calculate_average()` function calculates the average by summing all grades and dividing by the number of students.
